        'stopping_strings': ['<|end_of_turn|>', '<|im_end|>', 'Observation']
    }

    response = requests.post(uri, json=request)
    if response.status_code == 200:
        result = response.json()['results'][0]['text']
        return '\nThought:'+result if force_model else result

